validator:
function validate(input) {
  const [{ Employees = [], EmployeeUNI = [] }] = input;
  const ids = new Set(), pairs = new Set();
  for (const [id] of Employees) {
    if (id === null) return 'Every employee needs an id.';
    if (ids.has(id)) return `Employee id ${id} appears twice.`;
    ids.add(id);
  }
  for (const [id, unique] of EmployeeUNI) {
    if (id === null || unique === null) return 'EmployeeUNI rows need both id and unique_id.';
    const key = `${id}|${unique}`;
    if (pairs.has(key)) return `The pair (${id}, ${unique}) appears twice in EmployeeUNI.`;
    pairs.add(key);
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const int = n => Math.floor(rand() * n);
  const names = ['Alice', 'Bob', 'Meir', 'Winston', 'Jonathan', 'Sara', 'Omar', 'Lee'];
  const pool = small ? 10 : 3000;
  const ids = [];
  for (let id = 1; id <= pool; id++) if (rand() < (small ? 0.5 : 0.6)) ids.push(id);
  for (let i = ids.length - 1; i > 0; i--) { const j = int(i + 1); [ids[i], ids[j]] = [ids[j], ids[i]]; }
  const Employees = ids.slice(0, small ? int(9) : 1800).map(id => [id, small ? names[int(names.length)] : `Emp${id}`]);
  // Unique ids go to existing employees, to ids nobody has, and now and then a second one to the same employee.
  const EmployeeUNI = [], seen = new Set();
  const target = small ? int(9) : 1800;
  for (let tries = 0; EmployeeUNI.length < target && tries < target * 4; tries++) {
    const id = rand() < 0.8 && Employees.length ? Employees[int(Employees.length)][0] : 1 + int(pool + 2);
    const unique = 1 + int(small ? 6 : 5000);
    const key = `${id}|${unique}`;
    if (seen.has(key)) continue;
    seen.add(key);
    EmployeeUNI.push([id, unique]);
  }
  return [{ Employees, EmployeeUNI }];
}
